package com.railyatra.booking;
import com.railyatra.railway.service.SeatAllocationResult; import java.math.BigDecimal; import java.time.Instant; import java.time.LocalDate; import java.util.List;
public record BookingResponse(String id, String internalBookingReference, String providerPnr, String providerType, BookingStatus status, BookingStatus bookingStatus, Integer bookingStatusPosition, BookingStatus currentStatus, Integer currentStatusPosition, String trainNumber, String classCode, LocalDate journeyDate, String originStationCode, String destinationStationCode, BigDecimal totalFare, String paymentReference, Instant createdAt, List<SeatAllocationResult.AssignedSeat> seats) {
 static BookingResponse from(Booking b, List<SeatAllocationResult.AssignedSeat> seats) { return new BookingResponse(b.getId(),b.getInternalBookingReference(),b.getProviderPnr(),b.getProviderType(),b.getStatus(),b.getBookingStatus(),b.getBookingStatusPosition(),b.getCurrentStatus(),b.getCurrentStatusPosition(),b.getTrain().getTrainNumber(),b.getTrainClass().getClassCode(),b.getJourneyDate(),b.getOriginStation().getStationCode(),b.getDestinationStation().getStationCode(),b.getTotalFare(),b.getPaymentReference(),b.getCreatedAt(),seats); }
}
